onClick:
{{
  Delete_Devis.run()
    .then(() => {
      // 1. Fermer la modale (laisse le nom actuel de ta modale)
      closeModal('modal_delete_BL');

      // 2. Notification de succès
      showAlert('Devis supprimé avec succès', 'success');

      // 3. Retour à la page précédente ou à la page Devis principale
      navigateTo(appsmith.store.page_precedente || 'Devis');
    })
    .catch((error) => {
      showAlert('Erreur lors de la suppression : ' + error.message, 'error');
    });
}}
